// Interfaces for destination data
interface Attraction {
  name: string;
  image: string;
  description: string;
  rating: number;
}

interface Hotel {
  name: string;
  image: string;
  description: string;
  price: string;
  rating: number;
}

interface Restaurant {
  name: string;
  image: string;
  description: string;
  priceRange: string;
  rating: number;
}

interface DestinationDetails {
  id: string;
  name: string;
  location: string;
  tagline: string;
  description: string;
  image: string;
  gallery?: string[];
  rating: number;
  reviewCount: number;
  price: number;
  duration?: string;
  bestTime: string;
  category: string;
  travelCategories?: string[];
  attractions?: Attraction[];
  hotels?: Hotel[];
  restaurants?: Restaurant[];
  activities?: string[];
}

