const DestinationDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [destination, setDestination] = useState<DestinationDetails | null>(null);
  const [loading, setLoading] = useState(true);
  
  useEffect(() => {
    // Scroll to top when component mounts
    window.scrollTo(0, 0);
    
    // Find the destination in our data
    if (id) {
      const basicInfo = destinations.find(dest => dest.id === id);
      
      if (basicInfo) {
        // Merge basic info with extended info if available
        const extendedInfo = extendedDestinations[id] || {};
        const fullDestination = {
          ...basicInfo,
          ...extendedInfo,
          // If travelCategories is not provided, use category
          travelCategories: extendedInfo.travelCategories || [basicInfo.category],
          // Default gallery if not provided
          gallery: extendedInfo.gallery || [basicInfo.image, basicInfo.image, basicInfo.image, basicInfo.image],
          // Default duration if not provided
          duration: extendedInfo.duration || "3-5 days",
        };
        
        setDestination(fullDestination as DestinationDetails);
      } else {
        // Destination not found
        navigate("/destinations", { replace: true });
      }
    }
    
    setLoading(false);
  }, [id, navigate]);

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center">
        <p className="text-lg">Loading destination information...</p>
      </div>
    );
  }

  if (!destination) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center">
        <p className="text-lg text-red-500">Destination not found</p>
        <Button asChild className="mt-4">
          <Link to="/destinations">Back to Destinations</Link>
        </Button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar />
      
      <main className="flex-grow pt-24 pb-16 bg-gray-50 dark:bg-gray-900/50 animate-fade-in">
        {/* Hero Section */}
        <div className="relative h-[50vh] md:h-[60vh] overflow-hidden">
          <img 
            src={destination.image} 
            alt={destination.name} 
            className="absolute inset-0 w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/30 to-transparent">
            <div className="container mx-auto px-4 h-full flex flex-col justify-end pb-8">
              <Link to="/destinations" className="inline-flex items-center text-white mb-6 hover:text-blue-300 transition-colors">
                <ChevronLeft className="h-5 w-5 mr-1" />
                Back to Destinations
              </Link>
              
              <div className="flex flex-wrap gap-2 mb-4">
                {destination.travelCategories.map((category) => (
                  <span 
                    key={category} 
                    className="px-3 py-1 bg-blue-600/80 text-white text-xs font-medium rounded-full"
                  >
                    {category}
                  </span>
                ))}
              </div>
              
              <h1 className="text-3xl md:text-5xl font-bold text-white mb-2">{destination.name}</h1>
              <p className="text-xl text-white/90 mb-4">{destination.tagline}</p>
              
              <div className="flex flex-wrap items-center gap-4 text-white">
                <div className="flex items-center">
                  <MapPin className="h-5 w-5 mr-1 text-blue-400" />
                  <span>{destination.location}</span>
                </div>
                
                <div className="flex items-center">
                  <Star className="h-5 w-5 mr-1 text-yellow-400" fill="currentColor" />
                  <span>{destination.rating} ({destination.reviewCount} reviews)</span>
                </div>
                
                <div className="flex items-center">
                  <Clock className="h-5 w-5 mr-1 text-blue-400" />
                  <span>Best time: {destination.bestTime}</span>
                </div>
                
                <div className="flex items-center">
                  <Calendar className="h-5 w-5 mr-1 text-blue-400" />
                  <span>Suggested: {destination.duration}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
        
        {/* Main Content */}
        <div className="container mx-auto px-4 py-8">
          {/* Gallery */}
          {destination.gallery && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
              {destination.gallery.map((image, index) => (
                <div 
                  key={index} 
                  className={`rounded-lg overflow-hidden h-40 md:h-60`}
                >
                  <img 
                    src={image} 
                    alt={`${destination.name} gallery ${index+1}`} 
                    className="w-full h-full object-cover"
                    onError={(e) => {
                      const target = e.target as HTMLImageElement;
                      target.onerror = null;
                      target.src = "https://placehold.co/600x400/png?text=Image+Not+Available";
                    }}
                  />
                </div>
              ))}
            </div>
          )}
          
          {/* Action Buttons */}
          <div className="mb-12 flex flex-wrap justify-center gap-4">
            <Link to="/trip-planner">
              <AnimatedButton className="group bg-blue-600 hover:bg-blue-700">
                <Compass className="mr-2 h-4 w-4" />
                <span>Plan Trip Here</span>
              </AnimatedButton>
            </Link>
            
            <Button variant="outline" className="flex items-center">
              <Heart className="mr-2 h-4 w-4" />
              <span>Save to Favorites</span>
            </Button>
            
            <Button variant="outline" className="flex items-center">
              <Users className="mr-2 h-4 w-4" />
              <span>Share</span>
            </Button>
          </div>
          
          {/* Description */}
          <div className="max-w-4xl mx-auto mb-12">
            <h2 className="text-2xl font-bold mb-4 text-gray-900 dark:text-white">About {destination.name}</h2>
            <p className="text-gray-700 dark:text-gray-300 text-lg mb-6">{destination.description}</p>
            
            <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-sm">
              <h3 className="text-xl font-semibold mb-4 text-gray-900 dark:text-white">Trip Overview</h3>
              
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="flex items-start space-x-3">
                  <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center flex-shrink-0">
                    <Calendar className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-900 dark:text-white">Best Time to Visit</h4>
                    <p className="text-gray-600 dark:text-gray-400">{destination.bestTime}</p>
                  </div>
                </div>
                
                <div className="flex items-start space-x-3">
                  <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center flex-shrink-0">
                    <Clock className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-900 dark:text-white">Ideal Duration</h4>
                    <p className="text-gray-600 dark:text-gray-400">{destination.duration}</p>
                  </div>
                </div>
                
                <div className="flex items-start space-x-3">
                  <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center flex-shrink-0">
                    {destination.location.includes("India") ? (
                      <IndianRupee className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                    ) : (
                      <DollarSign className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                    )}
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-900 dark:text-white">Average Cost</h4>
                    <p className="text-gray-600 dark:text-gray-400">
                      {destination.location.includes("India") ? (
                        <>From ₹{destination.price} per person</>
                      ) : (
                        <>From ${destination.price} per person</>
                      )}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
          
          {/* Tabs for Attractions, Hotels, Restaurants */}
          {(destination.attractions || destination.hotels || destination.restaurants) && (
            <div className="max-w-6xl mx-auto">
              <Tabs defaultValue="attractions">
                <TabsList className="grid w-full grid-cols-3 mb-8 sticky top-20 bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm z-10">
                  <TabsTrigger value="attractions">Attractions</TabsTrigger>
                  <TabsTrigger value="hotels">Where to Stay</TabsTrigger>
                  <TabsTrigger value="dining">Where to Eat</TabsTrigger>
                </TabsList>
                
                <TabsContent value="attractions">
                  <h2 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">Top Attractions</h2>
                  
                  {destination.attractions ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                      {destination.attractions.map((attraction) => (
                        <div 
                          key={attraction.name} 
                          className="flex flex-col md:flex-row gap-4 bg-white dark:bg-gray-800 rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                        >
                          <div className="w-full md:w-1/3 h-48 md:h-auto">
                            <img 
                              src={attraction.image} 
                              alt={attraction.name} 
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                target.onerror = null;
                                target.src = "https://placehold.co/600x400/png?text=Image+Not+Available";
                              }}
                            />
                          </div>
                          <div className="p-4 md:p-6 flex-1">
                            <div className="flex justify-between items-start mb-2">
                              <h3 className="text-xl font-semibold text-gray-900 dark:text-white">{attraction.name}</h3>
                              <div className="flex items-center">
                                <Star className="h-4 w-4 text-yellow-400 mr-1" fill="currentColor" />
                                <span className="text-sm font-medium">{attraction.rating}</span>
                              </div>
                            </div>
                            <p className="text-gray-600 dark:text-gray-400 mb-4">{attraction.description}</p>
                            <Button variant="outline" size="sm">View Details</Button>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-gray-600 dark:text-gray-400 text-center py-8">
                      Detailed attraction information coming soon!
                    </p>
                  )}
                  
                  {destination.activities && (
                    <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-6 mb-8">
                      <h3 className="text-xl font-semibold mb-4 text-gray-900 dark:text-white">Popular Activities</h3>
                      <div className="flex flex-wrap gap-3">
                        {destination.activities.map((activity) => (
                          <div 
                            key={activity} 
                            className="px-4 py-2 bg-white dark:bg-gray-800 rounded-full shadow-sm text-sm text-gray-800 dark:text-gray-200"
                          >
                            {activity}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </TabsContent>
                
                <TabsContent value="hotels">
                  <h2 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">Recommended Accommodations</h2>
                  
                  {destination.hotels ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                      {destination.hotels.map((hotel) => (
                        <div 
                          key={hotel.name} 
                          className="flex flex-col md:flex-row gap-4 bg-white dark:bg-gray-800 rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                        >
                          <div className="w-full md:w-1/3 h-48 md:h-auto">
                            <img 
                              src={hotel.image} 
                              alt={hotel.name} 
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                target.onerror = null;
                                target.src = "https://placehold.co/600x400/png?text=Image+Not+Available";
                              }}
                            />
                          </div>
                          <div className="p-4 md:p-6 flex-1">
                            <div className="flex justify-between items-start mb-2">
                              <h3 className="text-xl font-semibold text-gray-900 dark:text-white">{hotel.name}</h3>
                              <div className="flex items-center">
                                <Star className="h-4 w-4 text-yellow-400 mr-1" fill="currentColor" />
                                <span className="text-sm font-medium">{hotel.rating}</span>
                              </div>
                            </div>
                            <p className="text-gray-600 dark:text-gray-400 mb-2">{hotel.description}</p>
                            <p className="text-blue-600 dark:text-blue-400 font-medium mb-4">{hotel.price}</p>
                            <Button variant="outline" size="sm">Check Availability</Button>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-gray-600 dark:text-gray-400 text-center py-8">
                      Accommodation details coming soon!
                    </p>
                  )}
                </TabsContent>
                
                <TabsContent value="dining">
                  <h2 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">Where to Eat</h2>
                  
                  {destination.restaurants ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                      {destination.restaurants.map((restaurant) => (
                        <div 
                          key={restaurant.name} 
                          className="flex flex-col md:flex-row gap-4 bg-white dark:bg-gray-800 rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                        >
                          <div className="w-full md:w-1/3 h-48 md:h-auto">
                            <img 
                              src={restaurant.image} 
                              alt={restaurant.name} 
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                target.onerror = null;
                                target.src = "https://placehold.co/600x400/png?text=Image+Not+Available";
                              }}
                            />
                          </div>
                          <div className="p-4 md:p-6 flex-1">
                            <div className="flex justify-between items-start mb-2">
                              <h3 className="text-xl font-semibold text-gray-900 dark:text-white">{restaurant.name}</h3>
                              <div className="flex items-center">
                                <Star className="h-4 w-4 text-yellow-400 mr-1" fill="currentColor" />
                                <span className="text-sm font-medium">{restaurant.rating}</span>
                              </div>
                            </div>
                            <p className="text-gray-600 dark:text-gray-400 mb-2">{restaurant.description}</p>
                            <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                              Price range: {restaurant.priceRange}
                            </p>
                            <Button variant="outline" size="sm">See Menu</Button>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-gray-600 dark:text-gray-400 text-center py-8">
                      Restaurant recommendations coming soon!
                    </p>
                  )}
                </TabsContent>
              </Tabs>
            </div>
          )}
          
          {/* CTA Section */}
          <div className="max-w-4xl mx-auto mt-16 bg-blue-100 dark:bg-blue-900/30 rounded-xl p-8 text-center">
            <h2 className="text-2xl font-bold mb-4 text-gray-900 dark:text-white">Ready to explore {destination.name}?</h2>
            <p className="text-gray-700 dark:text-gray-300 mb-6">
              Create your personalized trip plan now and discover everything {destination.name} has to offer.
            </p>
            <div className="flex flex-col sm:flex-row justify-center gap-4">
              <Link to="/trip-planner">
                <AnimatedButton className="bg-blue-600 hover:bg-blue-700">
                  <span>Plan Your Trip</span>
                </AnimatedButton>
              </Link>
              <Button variant="outline">Contact a Travel Expert</Button>
            </div>
          </div>
        </div>
      </main>
      
      <Footer />
    </div>
  );
};

export default DestinationDetails;